type SearchResultsProps = {
  filteredProfessions: Discipline[] | undefined
  selectedProfessions: number[] | null
  searchString: string
  onProfessionSelected: (profession: Discipline) => Promise<void>
}

const SearchResults = ({
  filteredProfessions,
  selectedProfessions,
  searchString,
  onProfessionSelected,
}: SearchResultsProps): JSX.Element => (
  <ScopeContainer>
    {filteredProfessions?.map(profession => {
      const disabled = !!selectedProfessions?.includes(profession.id)
      return (
        <Pressable key={profession.id} onPress={() => onProfessionSelected(profession)} disabled={disabled}>
          {highlightText(splitTextBySearchString(profession.title, searchString), disabled)}
          <HorizontalLine />
        </Pressable>
      )
    })}
  </ScopeContainer>
)

{showSearchResults ? (
  <SearchResults
    filteredProfessions={filteredProfessions}
    selectedProfessions={selectedProfessions}
    searchString={searchString}
    onProfessionSelected={async profession => {
      await pushSelectedProfession(profession.id).then(() => {
        navigation.navigate('ManageSelection')
      })
    }}
  />
) : (
